"""Exact complete-frame crops only. Art and prop pixels are generated by GPT."""
from pathlib import Path
import hashlib
import json
from PIL import Image

ROOT = Path(__file__).resolve().parent
SOURCE_NAME = 'harvest-west-v2.png'
PHASES = ['crouch_reach', 'grasp_contact', 'retract_lift', 'rise_hold']
DURATIONS_MS = [180, 220, 280, 320]
TRANSLATION = (0, -13)

def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def build():
    source = ROOT / 'sources' / SOURCE_NAME
    im = Image.open(source).convert('RGBA')
    assert im.size == (2048, 768), f'Unreviewed source canvas: {im.size}; never automatically resize'
    frames = []
    sheet = Image.new('RGBA', (2048, 768))
    for index, phase in enumerate(PHASES):
        crop = [index * 512, 0, (index + 1) * 512, 768]
        frame = Image.new('RGBA', (512, 768))
        frame.paste(im.crop(crop), TRANSLATION)
        output = ROOT / f'registered/harvest_west_{index}.png'
        frame.save(output)
        sheet.paste(frame, (index * 512, 0))
        frames.append({'pose_id': f'harvest_west_{index}', 'phase': phase,
                       'source': 'sources/' + SOURCE_NAME, 'source_sha256': sha(source),
                       'source_rect_px': crop, 'whole_frame_translation_px': TRANSLATION,
                       'scale': 1, 'alpha_processing': 'none; source alpha preserved',
                       'output': str(output.relative_to(ROOT)), 'sha256': sha(output),
                       'alpha_bbox_px': frame.getchannel('A').getbbox(),
                       'duration_ms': DURATIONS_MS[index]})
    sheet.save(ROOT / 'registered/harvest-west-a-sheet.png')
    manifest = {'schema_version': 1, 'template_id': 'adult-standard-v1',
                'motion_set_id': 'harvest-west-proof-v1', 'action_id': 'harvest', 'direction': 'west',
                'status': 'rejected', 'user_accepted': False,
                'canvas_px': [512, 768], 'root_anchor_px': [256, 708],
                'root_anchor_scope': 'nominal review origin only; actual foot stance is not stable across poses',
                'density_check': 'failed: source terminal opaque body height644px vs582px reference; approximately153px displayed vs138px reference at identical scale',
                'planting_check': 'failed: near/far shoes slide left during rise; not corrected by per-part moves',
                'display_scale': 138/582, 'reference_standing_character_display_height_px': 138,
                'cycle_duration_ms': sum(DURATIONS_MS),
                'move_policy': 'stationary full-frame proof; no gameplay execution',
                'repeat_policy': 'review-only replay; terminal rise_hold is followed by crouch restart without a production transition',
                'event': {'id': 'visual_grasp_only', 'frame_index': 1,
                          'time_ms': DURATIONS_MS[0], 'gameplay_transaction': False},
                'registration_script_sha256': sha(Path(__file__)), 'frames': frames}
    (ROOT/'registered/registration.json').write_text(json.dumps(manifest, indent=2)+'\n')
    print(json.dumps({'frames': 4, 'canvas': [512,768], 'source_sha256': sha(source)}))

if __name__ == '__main__':
    build()
